  'molen.entities.rail.autorack_enclosed': { doc: '89 ft enclosed bi-level autorack: flatcar with a fishbelly centre sill under a fully enclosed rack of perforated side panels, arched roof and two-leaf end doors. Unpowered car for track-guided consists; vehicle.color repaints the rack frame, posts and fascia.' },
  'molen.entities.rail.bombardier_bilevel_cab_car': { doc: 'Bombardier BiLevel commuter cab car: the BiLevel coach with an operating cab at the front (+Z) end (windscreen, headlights, ditch lights, horn, driver desk and seat with live throttle and brake handles) for push-pull service. Unpowered: it leads a consist pushed by a locomotive; passengers board through the passenger seats.' },
  'molen.entities.rail.bombardier_bilevel_coach': { doc: 'Bombardier BiLevel commuter coach: low-floor lower level between the trucks, upper level under the characteristic sloping upper sides, intermediate-level vestibules over the trucks with side doors, seats on both levels, stairs, luggage racks and ceiling lights. Unpowered car for track-guided consists; passengers board through the passenger seats.' },
  'molen.entities.rail.boxcar_50ft': { doc: '50 ft high-cube (plate F) boxcar: single 10 ft plug door, exterior posts, corrugated ends, peaked roof, three-piece trucks with 36 in wheels. Unpowered car for track-guided consists; vehicle.color repaints the carbody.' },
  'molen.entities.rail.centerbeam_flatcar': { doc: '73 ft centerbeam flatcar: open lattice centre partition between end bulkheads over a fishbelly centre sill, loaded with wrapped lumber bundles leaning on the beam and strapped to side-sill winches (node load). Unpowered car for track-guided consists; vehicle.color repaints the car.' },
  'molen.entities.rail.covered_hopper': { doc: 'Three-bay 5,161 cu ft covered hopper for grain and plastics: exterior-post sides, sloped end sheets over end platforms, three hopper bays with outlet gates, continuous roof trough hatch. Unpowered car for track-guided consists; vehicle.color repaints the carbody.' },
  'molen.entities.rail.emd_gp38_2': { doc: 'EMD GP38-2: four-axle road switcher for yards and locals, with a low short hood, standard cab, Blomberg B trucks with 40 in wheels, dynamic-brake blister and two radiator fans, in a generic two-tone livery. Full cab interior (AAR control stand, 26L brake stand, live throttle and automatic brake handles, engineer and conductor seats). Drives on track with locked steering.' },
  'molen.entities.rail.ge_es44ac': { doc: 'GE ES44AC (Evolution Series): six-axle AC road freight locomotive with a wide-nose safety cab, C-C Hi-Ad trucks with 42 in wheels, dynamic-brake housing behind the cab and the flared radiator section at the rear, in a generic two-tone livery. Full cab interior (desktop console, live throttle and automatic brake handles, engineer and conductor seats). Drives on track: steering is locked, power at the rail limits tractive effort above starting speed.' },
  'molen.entities.rail.gondola_52ft': { doc: '52 ft mill gondola with exterior-post sides, fixed ends and a steel floor, carrying a heaped scrap load (node load, hideable). Unpowered car for track-guided consists; vehicle.color repaints the carbody.' },
  'molen.entities.rail.mpi_mp36ph_3c': { doc: 'MPI MP36PH-3C: cab-forward commuter passenger locomotive with a full-width cowl carbody, raked windscreen, head-end-power compartment behind the cab, Blomberg B trucks with 40 in wheels, in a generic commuter livery (rail-livery-stripe band, rail-livery-accent pinstripe). Full cab interior (desktop console, live throttle and automatic brake handles, engineer and conductor seats). Drives on track with locked steering.' },
  'molen.entities.rail.tank_car_dot117': { doc: 'DOT-117J jacketed general-service tank car of about 30,000 gal: sloped-bottom shell, integral full-height head shields, top fittings protective housing, centre ladders, end platforms, bottom outlet with skid. Unpowered car for track-guided consists; vehicle.color repaints the tank.' },
  'molen.entities.rail.well_car_double_stack': { doc: 'Single-unit 53 ft intermodal well car carrying two unbranded 53 ft high-cube containers stacked in the well (node load; materials container-lower and container-upper recolour each box). Unpowered car for track-guided consists; vehicle.color repaints the car body.' },
